from datetime import timedelta


class SpyBullishCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            fill_forward=False,
            leverage=1,
            extendedMarketHours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = RollingWindow[float](self.slow_period)

        self._minute_bars = {}
        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._no_entry_today = False
        self._last_session_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self._last_session_date != current_date:
            self._last_session_date = current_date
            self._no_entry_today = False

        # Do not intentionally hold options into expiration.
        if self._held_symbol is not None:
            expiration_date = self._held_symbol.ID.Date.date()

            if current_date >= expiration_date:
                self._no_entry_today = True
                self._LiquidateHeldOption("expiration processing")
            elif self._IsExpirationEve(current_date, expiration_date):
                if self.Time.hour == 15 and self.Time.minute >= 45:
                    self._LiquidateHeldOption("expiration-eve time stop")

        self._HandleUnexpectedSpyPosition()

        if self._held_symbol is not None:
            self._EvaluateProfitTarget(slice)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None:
            return

        self._ProcessMinuteBar(spy_bar, slice)

    def _ProcessMinuteBar(self, minute_bar: TradeBar, slice: Slice):
        local_time = minute_bar.EndTime.astimezone(self.TimeZone)
        session_date = local_time.date()

        if local_time.hour < 9 or local_time.hour > 15:
            return
        if local_time.hour == 9 and local_time.minute <= 30:
            return
        if local_time.hour == 15 and local_time.minute > 59:
            return

        minute = local_time.minute
        bucket_end_minute = ((minute // 5) * 5) + 5
        bucket_end = local_time.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=bucket_end_minute)

        key = bucket_end
        self._minute_bars.setdefault(key, []).append(minute_bar)

        if minute != bucket_end.minute - 1:
            return

        bars = self._minute_bars.pop(key, [])
        if len(bars) != 5:
            # Missing minute data means the five-minute bar is discarded.
            return

        bars.sort(key=lambda bar: bar.Time)
        expected_times = [
            bars[0].Time + timedelta(minutes=i) for i in range(5)
        ]
        if [bar.Time for bar in bars] != expected_times:
            return

        consolidated = TradeBar(
            bars[0].Time,
            self.spy.Symbol,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self._OnFiveMinuteBar(consolidated, slice)

    def _OnFiveMinuteBar(self, bar: TradeBar, slice: Slice):
        current_close = float(bar.Close)
        previous_fast = None
        previous_slow = None

        if self.closes.IsReady:
            previous_fast = sum(
                float(self.closes[i]) for i in range(self.fast_period)
            ) / self.fast_period
            previous_slow = sum(
                float(self.closes[i]) for i in range(self.slow_period)
            ) / self.slow_period

        self.closes.Add(current_close)

        if not self.closes.IsReady:
            return

        current_fast = sum(
            float(self.closes[i]) for i in range(self.fast_period)
        ) / self.fast_period
        current_slow = sum(
            float(self.closes[i]) for i in range(self.slow_period)
        ) / self.slow_period

        if previous_fast is None or previous_slow is None:
            return

        end_time = bar.EndTime.astimezone(self.TimeZone)
        eligible_time = (
            end_time.hour > 9 or
            (end_time.hour == 9 and end_time.minute >= 45)
        ) and (
            end_time.hour < 14 or
            (end_time.hour == 14 and end_time.minute <= 30)
        )

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if (
            bullish_cross and
            eligible_time and
            not self._no_entry_today and
            self._held_symbol is None and
            not self._EntryOrderIsOpen()
        ):
            self._TryEnter(slice, current_close)

    def _TryEnter(self, slice: Slice, spy_price: float):
        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Submitted entry for {0}, expiration {1}, strike {2}.".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None and
            order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {0} at {1}.".format(
                        self._held_symbol, self._entry_price
                    )
                )
                self._entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Nullified
            ):
                self._entry_ticket = None

        if (
            self._exit_ticket is not None and
            order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}.".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Nullified
            ):
                self._exit_ticket = None

    def _EvaluateProfitTarget(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return
        if self._exit_ticket is not None:
            return

        quote = slice.QuoteBars.get(self._held_symbol)
        if quote is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._SubmitExit("50% profit target")

    def _LiquidateHeldOption(self, reason: str):
        if self._held_symbol is None:
            return
        self._SubmitExit(reason)

    def _SubmitExit(self, reason: str):
        if self._exit_ticket is not None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity
        )
        self._no_entry_today = True
        self.Debug(
            "Submitted exit for {0}: {1}.".format(
                self._held_symbol, reason
            )
        )

    def _EntryOrderIsOpen(self):
        if self._entry_ticket is None:
            return False

        status = self._entry_ticket.Status
        return status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _IsExpirationEve(self, current_date, expiration_date):
        next_trading_day = self.Securities[
            self.spy.Symbol
        ].Exchange.Hours.GetNextTradingDay(current_date)

        return next_trading_day.date() == expiration_date

    def _HandleUnexpectedSpyPosition(self):
        spy_quantity = self.Portfolio[self.spy.Symbol].Quantity
        if spy_quantity == 0:
            return

        self.Debug(
            "Unexpected SPY equity position detected; liquidating {0} shares.".format(
                spy_quantity
            )
        )
        self._no_entry_today = True
        self.MarketOrder(self.spy.Symbol, -spy_quantity)

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            "Unexpected exercise or assignment processed for {0}; liquidating SPY.".format(
                assignment_event.Symbol
            )
        )
        self._no_entry_today = True
        self._HandleUnexpectedSpyPosition()

